mapper.select:
select cast(id as char) keyId,name,key_type keyType,cast(application_id as char) applicationId,public_id publicId,
  display_suffix displaySuffix,scopes,status,created_at createdAt,last_used_at lastUsedAt,revoked_at revokedAt
from p_access_key where account_id=#{accountId} and key_type=#{type}
and application_id=#{applicationId}
order by created_at desc,id desc
